return [{json: (function snapshot(c, commit) {
  if (!/^[a-f0-9]{40}$/.test(commit.sha || '')) throw new Error('GitHub: ungueltiger Commit');
  return {...c, source_commit_sha: commit.sha};
})($('Konfiguration').first().json, $input.first().json)}];

return [{json: (function inventory(c, tree) {
  if (tree.truncated !== false || !Array.isArray(tree.tree)) {
    throw new Error('GitHub-Inventar unvollstaendig. Keine Indexierung.');
  }
  const selected = c.documents.map(d => {
    const path = c.root + '/' + d.path;
    const matches = tree.tree.filter(t => t.path === path);
    if (matches.length !== 1 || matches[0].type !== 'blob' || matches[0].mode !== '100644') {
      throw new Error('Wissensdatei fehlt oder ist keine regulaere Datei: ' + path);
    }
    const f = matches[0];
    if (!/^[a-f0-9]{40}$/.test(f.sha) || !Number.isInteger(f.size) || f.size < 1 || f.size > 100000) {
      throw new Error('Ungueltige oder zu grosse Wissensdatei: ' + path);
    }
    return {document_code:d.document_code, file_path:path, blob_sha:f.sha};
  });
  return {...c, selected};
})($('Commit festhalten').first().json, $input.first().json)}];

return [{json: (function plan(c, state) {
  if (!state || !Array.isArray(state.documents)) throw new Error('Ungueltiger Supabase-Indexstatus');
  const tasks = [], skipped = [];
  for (const d of c.selected) {
    const found = state.documents.filter(s => s.file_path === d.file_path);
    if (found.length > 1) throw new Error('Doppelter Dokumentpfad im Index');
    const old = found[0];
    if (old && (old.document_code !== d.document_code || !old.indexed_at)) {
      throw new Error('Inkonsistente Dokumentidentitaet: ' + d.file_path);
    }
    const same = old && old.blob_sha === d.blob_sha && old.embedding_model === c.embedding_model
      && old.embedding_dimensions === c.embedding_dimensions
      && old.index_config_version === c.index_config_version && old.chunk_count > 0;
    if (same) skipped.push(d.document_code);
    else tasks.push({...d, expected_indexed_at:old ? old.indexed_at : null});
  }
  return {...c, tasks, skipped};
})($input.first().json, $('Supabase Indexstand').first().json)}];

const tasks = $('Dokumentauftraege').all();
const inputs = $input.all();
if (tasks.length !== inputs.length) throw new Error('GitHub: unvollstaendige Dateiantworten');
return inputs.map((item,i)=>({json:(function chunk(c, task, blob) {
  if (blob.sha !== task.blob_sha || blob.encoding !== 'base64' || typeof blob.content !== 'string') {
    throw new Error('GitHub-Blob stimmt nicht mit Inventar ueberein');
  }
  const bytes = Buffer.from(blob.content.replace(/\s/g, ''), 'base64');
  const text = bytes.toString('utf8').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
  if (bytes.length > 100000 || text.includes('\uFFFD') || text.includes('\0')) {
    throw new Error('Datei ist kein gueltiger UTF-8-Text oder zu gross');
  }
  const fm = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (!fm) throw new Error('Dokumentmetadaten fehlen');
  const meta = {};
  for (const line of fm[1].split('\n')) {
    const m = line.match(/^([a-z_]+):\s*(.+)$/);
    if (!m || Object.hasOwn(meta, m[1])) throw new Error('Ungueltige oder doppelte Metadaten');
    meta[m[1]] = m[2].replace(/^(['"])(.*)\1$/, '$2');
  }
  if (meta.document_id !== task.document_code || meta.status !== 'freigegeben'
      || meta.datenart !== 'fiktive_testdaten' || !meta.title || !meta.version
      || !/^\d{4}-\d{2}-\d{2}$/.test(meta.stand || '')) throw new Error('Dokumentmetadaten nicht freigegeben oder unvollstaendig');
  const body = text.slice(fm[0].length).trim();
  if (!body) throw new Error('Dokument ist leer');
  const sections = [];
  let section = meta.title, lines = [];
  for (const line of body.split('\n')) {
    const heading = line.match(/^#{1,3}\s+(.+)$/);
    if (heading) {
      if (lines.join('\n').trim()) sections.push({section, text:lines.join('\n').trim()});
      section = heading[1]; lines = [];
    } else lines.push(line);
  }
  if (lines.join('\n').trim()) sections.push({section, text:lines.join('\n').trim()});
  const chunks = [];
  for (const s of sections) {
    const prefix = meta.title + '\nAbschnitt: ' + s.section + '\n\n';
    const room = c.chunk_size - prefix.length;
    if (room <= c.overlap + 100) throw new Error('Ueberschrift zu lang');
    let start = 0;
    while (start < s.text.length) {
      let end = Math.min(start + room, s.text.length);
      if (end < s.text.length) {
        const window = s.text.slice(start, end);
        const boundary = Math.max(window.lastIndexOf('\n'), window.lastIndexOf(' '));
        if (boundary > room / 2) end = start + boundary;
      }
      const part = s.text.slice(start, end).trim();
      if (part) chunks.push({chunk_index:chunks.length, section:s.section, content:prefix + part});
      if (end === s.text.length) break;
      start = end - c.overlap;
    }
  }
  if (!chunks.length || chunks.length > 100) throw new Error('Ungueltige Chunk-Anzahl');
  return {document:{...task, repository:c.repository, branch:c.branch,
    source_commit_sha:c.source_commit_sha, title:meta.title, document_version:meta.version,
    document_date:meta.stand, embedding_model:c.embedding_model,
    embedding_dimensions:c.embedding_dimensions, index_config_version:c.index_config_version}, chunks};
})($('Indexierung planen').first().json,tasks[i].json,item.json),pairedItem:{item:i}}));

const prepared = $('Text und Chunks').all();
const inputs = $input.all();
if (prepared.length !== inputs.length) throw new Error('Embedding-Antwort fehlt');
return inputs.map((item,i)=>({json:(function vectors(prepared, response) {
  if (response.model !== prepared.document.embedding_model || !Array.isArray(response.data)
      || response.data.length !== prepared.chunks.length) throw new Error('Embedding-Antwort: Modell oder Anzahl falsch');
  const byIndex = new Map();
  for (const entry of response.data) {
    if (!Number.isInteger(entry.index) || entry.index < 0 || entry.index >= prepared.chunks.length
      || byIndex.has(entry.index) || !Array.isArray(entry.embedding)
      || entry.embedding.length !== 1536
      || !entry.embedding.every(v => typeof v === 'number' && Number.isFinite(v))
      || !entry.embedding.some(v => v !== 0)) throw new Error('Ungueltiger Embedding-Vektor');
    byIndex.set(entry.index, entry.embedding);
  }
  return {p_document:prepared.document,
    p_chunks:prepared.chunks.map(ch => ({...ch,embedding:byIndex.get(ch.chunk_index)}))};
})(prepared[i].json,item.json),pairedItem:{item:i}}));

return [{json: (function summary(p, results) {
  if (results.length !== p.tasks.length) throw new Error('Nicht alle Dokumente gespeichert');
  results.forEach((r, i) => {
    if (r.status !== 'indexed' || r.file_path !== p.tasks[i].file_path
        || r.blob_sha !== p.tasks[i].blob_sha || !Number.isInteger(r.chunk_count) || r.chunk_count < 1) {
      throw new Error('Speicherbestaetigung unvollstaendig');
    }
  });
  return {status:'completed', source_commit_sha:p.source_commit_sha,
    indexed_documents:results.length, skipped_documents:p.skipped,
    written_chunks:results.reduce((n,r)=>n+r.chunk_count,0), results,
    scope:'UC2: '+p.documents.length+' Dokumente; keine automatische Loeschung'};
})($('Indexierung planen').first().json, $input.all().map(i=>i.json))}];

return [{json: (function summary(p, results) {
  if (results.length !== p.tasks.length) throw new Error('Nicht alle Dokumente gespeichert');
  results.forEach((r, i) => {
    if (r.status !== 'indexed' || r.file_path !== p.tasks[i].file_path
        || r.blob_sha !== p.tasks[i].blob_sha || !Number.isInteger(r.chunk_count) || r.chunk_count < 1) {
      throw new Error('Speicherbestaetigung unvollstaendig');
    }
  });
  return {status:'completed', source_commit_sha:p.source_commit_sha,
    indexed_documents:results.length, skipped_documents:p.skipped,
    written_chunks:results.reduce((n,r)=>n+r.chunk_count,0), results,
    scope:'UC2: '+p.documents.length+' Dokumente; keine automatische Loeschung'};
})($input.first().json, [])}];
